package vaultor.linked;
import java.nio.file.*;import java.util.*;import java.io.*;

public final class Gate3Tests extends SafetyTests {
    static int unqualified;
    static class G3Fixture implements AutoCloseable {
        final Path dir=Files.createTempDirectory(Path.of("native/linked-markdown/.scratch"),"g3-").toAbsolutePath();
        final Path root=Files.createDirectory(dir.resolve("root")),file=root.resolve("doc.md"),journal=dir.resolve("private");
        LinkedStore store;String rootCap;LinkedStore.Opened document;
        G3Fixture(LinkedStore.Faults fault)throws Exception{
            Files.writeString(file,"Base documentation\r\n");store=new LinkedStore(OWNER,journal,VALIDATOR,CONSENT,List.of(dir.resolve("managed")),fault);store.useOriginalObjectWrites(OWNER);rootCap=grant(store,root);document=store.openRelative(OWNER,rootCap,"doc.md");
        }
        LinkedStore.Receipt save(String local)throws Exception{return store.save(OWNER,document.document(),document.epoch(),candidate(store,document,1,local),UUID.randomUUID().toString());}
        public void close()throws Exception{store.close();}
    }
    public static void main(String[] args)throws Exception{
        System.setProperty("vaultor.linked.g3.unsafe-publication-probe","true");
        if(args.length>0){crashChild(args);return;}
        Files.createDirectories(Path.of("native/linked-markdown/.scratch"));
        check("original-object Save preserves inode, owner/DACL, CRLF and exact bytes",()->{try(var f=new G3Fixture(null)){var receipt=f.save("Local 😀\r\n");require(receipt.state().equals("COMMITTED"));require(receipt.revision().identity().equals(f.document.base().revision().identity()));require(receipt.revision().metadata().equals(f.document.base().revision().metadata()));require(Arrays.equals(Files.readAllBytes(f.file),LinkedStore.utf8("Local 😀\r\n")));}});
        check("live writable mapping with closed file handle prevents original-object Save",()->{try(var f=new G3Fixture(null)){var child=process("vaultor.linked.MappedWriter",Base64.getEncoder().encodeToString(LinkedStore.utf8(f.file.toString())));require(new BufferedReader(new InputStreamReader(child.getInputStream())).readLine().equals("MAPPED"));try{require(f.save("Do not overwrite map").state().equals("RECOVERY_REQUIRED"));require(Files.readString(f.file).equals("Base documentation\r\n"));}finally{child.getOutputStream().write(1);child.getOutputStream().flush();require(child.waitFor()==0);}require(Files.readString(f.file).startsWith("Ease"));}});
        check("independent writer and rename are refused while original-object lease is active",()->{final Path[] file={null};try(var f=new G3Fixture((phase,op)->{if(phase.equals("original-before-write")){require(external("write",file[0],"External")==2);require(external("replace",file[0],"Replacement")==2);}})){file[0]=f.file;require(f.save("Local").state().equals("COMMITTED"));}});
        check("independent hardlink creation is refused during the original-object write lease",()->{final Path[] file={null},alias={null};try(var f=new G3Fixture((phase,op)->{if(phase.equals("original-before-write"))require(external("hardlink",alias[0],file[0].toString())==2);})){file[0]=f.file;alias[0]=f.dir.resolve("outside-alias.md");require(f.save("Local").state().equals("COMMITTED"));require(!Files.exists(alias[0]));}});
        check("partial original write is recovery-required with B/L/V intact and path present",()->{try(var f=new G3Fixture((phase,op)->{if(phase.equals("original-write-chunk"))throw new IOException("SIMULATED_ENOSPC");})){require(f.save("x".repeat(9000)).state().equals("RECOVERY_REQUIRED"));require(Files.exists(f.file));require(f.store.recover(OWNER).stream().anyMatch(r->r.record()!=null&&r.record().local()!=null&&r.record().local().length==9000&&Arrays.equals(r.record().base(),f.document.base().bytes())));}});
        check("reviewed repair preserves partial D and restores exact L on the same inode",()->{try(var f=new G3Fixture((phase,op)->{if(phase.equals("original-write-chunk"))throw new IOException("SIMULATED_ENOSPC");})){var saved=f.save("x".repeat(9000));byte[] partial=Files.readAllBytes(f.file);var review=f.store.reviewRecovery(OWNER,saved.operation(),f.rootCap);require(review.state().equals("SAME_ORIGINAL_OBJECT"));require(f.store.repairRecovery(OWNER,review.ticket(),"local").state().equals("RECOVERY_REPAIRED_REOPEN_REQUIRED"));require(Files.readString(f.file).equals("x".repeat(9000)));require(f.store.recover(OWNER).stream().anyMatch(r->r.record()!=null&&Arrays.equals(r.record().base(),partial)));rejects("REVIEW_STALE",()->f.store.repairRecovery(OWNER,review.ticket(),"base"));}});
        check("external D changing after review refuses repair without touching it",()->{try(var f=new G3Fixture(null)){var saved=f.save("Local");var review=f.store.reviewRecovery(OWNER,saved.operation(),f.rootCap);require(external("write",f.file,"External after review")==0);rejects("RECOVERY_DISK_CHANGED",()->f.store.repairRecovery(OWNER,review.ticket(),"base"));require(Files.readString(f.file).equals("External after review"));}});
        check("reused pathname remains independent even when bytes match",()->{try(var f=new G3Fixture(null)){var saved=f.save("Local");require(external("replace",f.file,"Local")==0);var review=f.store.reviewRecovery(OWNER,saved.operation(),f.rootCap);require(review.state().equals("INDEPENDENT_OCCUPANT"));rejects("INDEPENDENT",()->f.store.repairRecovery(OWNER,review.ticket(),"base"));rejects("INDEPENDENT",()->f.store.restoreMissingBase(OWNER,f.store.reviewRecovery(OWNER,saved.operation(),f.rootCap).ticket()));require(Files.readString(f.file).equals("Local"));}});
        check("same-file external conflict requires reviewed resolution and retains external B",()->{try(var f=new G3Fixture(null)){String ticket=candidate(f.store,f.document,1,"Chosen local");require(external("write",f.file,"External before Save")==0);var conflict=f.store.save(OWNER,f.document.document(),f.document.epoch(),ticket,UUID.randomUUID().toString());require(conflict.state().equals("CONFLICT"));var review=f.store.reviewRecovery(OWNER,conflict.operation(),f.rootCap);require(f.store.repairRecovery(OWNER,review.ticket(),"local").state().equals("RECOVERY_REPAIRED_REOPEN_REQUIRED"));require(Files.readString(f.file).equals("Chosen local"));require(f.store.recover(OWNER).stream().anyMatch(r->r.record()!=null&&Arrays.equals(r.record().base(),LinkedStore.utf8("External before Save")))) ;}});
        check("explicit recovery exports B/L/V with owner-only ACL and never overwrite a source",()->{try(var f=new G3Fixture(null)){var saved=f.save("Local 😀\r\n");for(String choice:List.of("base","local","visual")){String name="修復-"+choice+".md";f.store.exportRecovery(OWNER,saved.operation(),choice,f.rootCap,name);require(Files.size(f.root.resolve(name))>0);try(var h=WindowsFiles.lease(f.root.resolve(name),false)){require(WindowsFiles.security(h).protectedDacl());}rejects("ExportCreateNew",()->f.store.exportRecovery(OWNER,saved.operation(),choice,f.rootCap,name));}rejects("ExportCreateNew",()->f.store.exportRecovery(OWNER,saved.operation(),"visual",f.rootCap,"doc.md"));require(Files.readString(f.file).equals("Local 😀\r\n"));}});
        check("reviewed disk export is immutable and consumes its one-use review ticket",()->{try(var f=new G3Fixture(null)){var saved=f.save("Local");require(external("write",f.file,"Reviewed disk")==0);var review=f.store.reviewRecovery(OWNER,saved.operation(),f.rootCap);require(external("write",f.file,"Newer disk")==0);f.store.exportReviewedDisk(OWNER,review.ticket(),f.rootCap,"disk-copy.md");require(Files.readString(f.root.resolve("disk-copy.md")).equals("Reviewed disk"));require(Files.readString(f.file).equals("Newer disk"));rejects("REVIEW_STALE",()->f.store.repairRecovery(OWNER,review.ticket(),"base"));}});
        check("revocation invalidates repair tickets but leaves versions available to export",()->{try(var f=new G3Fixture(null)){var saved=f.save("Local");var review=f.store.reviewRecovery(OWNER,saved.operation(),f.rootCap);f.store.revoke(OWNER,f.rootCap);rejects("REVIEW_STALE",()->f.store.repairRecovery(OWNER,review.ticket(),"base"));require(Files.readString(f.file).equals("Local"));require(!f.store.recover(OWNER).isEmpty());}});
        check("full operation quota permits lifeboat export and explicit reviewed resolution",()->{try(var f=new G3Fixture(null)){var saved=f.save("Local");int used=f.store.recover(OWNER).size();for(int i=used;i<100;i++)Files.createDirectory(f.journal.resolve(UUID.randomUUID().toString()));f.store.exportRecovery(OWNER,saved.operation(),"visual",f.rootCap,"lifeboat.md");require(Files.readString(f.root.resolve("lifeboat.md")).contains("recover me"));var review=f.store.reviewRecovery(OWNER,saved.operation(),f.rootCap);f.store.resolveRecovery(OWNER,review.ticket());require(!Files.exists(f.journal.resolve(saved.operation())));require(Files.readString(f.file).equals("Local"));}});
        check("tampered-tail records can export prior valid bytes but cannot repair",()->{try(var f=new G3Fixture(null)){var saved=f.save("Local");Files.write(f.journal.resolve(saved.operation()).resolve("03.rec"),new byte[]{1,2,3});rejects("CORRUPT",()->f.store.reviewRecovery(OWNER,saved.operation(),f.rootCap));f.store.exportRecovery(OWNER,saved.operation(),"local",f.rootCap,"prior-valid.md");require(Files.readString(f.root.resolve("prior-valid.md")).equals("Local"));}});
        check("fully corrupt records export raw stage without granting source authority",()->{try(var f=new G3Fixture(null)){var saved=f.save("Local");Path op=f.journal.resolve(saved.operation());try(var list=Files.list(op)){for(Path file:list.filter(p->p.toString().endsWith(".rec")).toList())Files.write(file,new byte[]{9});}rejects("CORRUPT",()->f.store.reviewRecovery(OWNER,saved.operation(),f.rootCap));f.store.exportRecovery(OWNER,saved.operation(),"stage",f.rootCap,"raw-stage.md");require(Files.readString(f.root.resolve("raw-stage.md")).equals("Local"));}});
        check("group, owner, inherited DACL and mandatory label remain on the original object",()->{try(var f=new G3Fixture(null)){String before=MetadataAudit.security(f.file);var creation=Files.readAttributes(f.file,java.nio.file.attribute.BasicFileAttributes.class).creationTime();Files.setLastModifiedTime(f.file,java.nio.file.attribute.FileTime.fromMillis(100000));require(f.save("New content").state().equals("COMMITTED"));require(MetadataAudit.security(f.file).equals(before));var after=Files.readAttributes(f.file,java.nio.file.attribute.BasicFileAttributes.class);require(after.creationTime().equals(creation));require(after.lastModifiedTime().toMillis()>100000);}});
        check("real NTFS extended attributes survive original-object Save byte-for-byte",()->{try(var f=new G3Fixture(null)){MetadataAudit.setEa(f.file);String before=MetadataAudit.ea(f.file);require(f.save("EA content").state().equals("COMMITTED"));require(MetadataAudit.ea(f.file).equals(before));}});
        try(var f=new G3Fixture(null)){var process=new ProcessBuilder("icacls.exe",f.file.toString(),"/setintegritylevel","L").redirectErrorStream(true).start();process.getInputStream().readAllBytes();int exit=process.waitFor();if(exit!=0){unqualified++;results.add("UNQUALIFIED explicit integrity-label fixture: icacls exit="+exit+"; setter unavailable under current token. Direct writes refuse explicit labels; positive refusal fixture still requires suitable platform access.");}else check("explicit integrity label refuses direct editing without touching source",()->{require(f.save("Must refuse").state().equals("RECOVERY_REQUIRED"));require(Files.readString(f.file).equals("Base documentation\r\n"));});}
        check("legacy missing pathname restores captured original with full object identity",()->{try(var f=new Fixture((phase,op)->{if(phase.equals("captured"))throw new IOException("STOP_AFTER_CAPTURE");})){var saved=f.save(f.prepare("Legacy local"));require(!Files.exists(f.file));var review=f.store.reviewRecovery(OWNER,saved.operation(),f.rootCap);require(review.state().equals("PATH_MISSING"));require(f.store.restoreMissingBase(OWNER,review.ticket()).state().equals("BASE_RESTORED_REOPEN_REQUIRED"));require(Files.readString(f.file).equals("Base\r\n"));require(f.store.reconcile(OWNER,f.doc.document()).disk().revision().identity().equals(f.doc.base().revision().identity()));}});
        check("an interloper filling a reviewed missing path is never overwritten by restore",()->{try(var f=new Fixture((phase,op)->{if(phase.equals("captured"))throw new IOException("STOP_AFTER_CAPTURE");})){var saved=f.save(f.prepare("Legacy local"));var review=f.store.reviewRecovery(OWNER,saved.operation(),f.rootCap);require(external("create",f.file,"Independent occupant")==0);rejects("RenameRelativeExclusive",()->f.store.restoreMissingBase(OWNER,review.ticket()));require(Files.readString(f.file).equals("Independent occupant"));}});
        for(String phase:List.of("original-prepared","original-staged","original-before-write","original-write-chunk","original-before-flush","original-flushed","original-committed"))check("actual process halt and explicit repair at "+phase,()->originalCrash(phase));
        Files.createDirectories(Path.of("native/linked-markdown/evidence/g3"));Files.writeString(Path.of("native/linked-markdown/evidence/g3/native-tests.txt"),String.join("\n",results)+"\npassed="+passed+" failed="+failed+" unqualified="+unqualified+"\n");if(failed>0)System.exit(1);
    }
    static void crashChild(String[] args)throws Exception{
        Path directory=Path.of(args[1]);try(var store=new LinkedStore(OWNER,directory.resolve("private"),VALIDATOR,CONSENT,List.of(directory.resolve("managed")),(phase,op)->{if(phase.equals(args[0]))Runtime.getRuntime().halt(75);})){store.useOriginalObjectWrites(OWNER);String root=grant(store,directory.resolve("root"));var opened=store.openRelative(OWNER,root,"doc.md");String candidate=candidate(store,opened,1,"L".repeat(9000));store.save(OWNER,opened.document(),opened.epoch(),candidate,UUID.randomUUID().toString());}
    }
    static void originalCrash(String phase)throws Exception{
        Path directory=Files.createTempDirectory(Path.of("native/linked-markdown/.scratch"),"g3-crash-").toAbsolutePath(),root=Files.createDirectory(directory.resolve("root")),file=root.resolve("doc.md");Files.writeString(file,"Original base\r\n");var child=process("vaultor.linked.Gate3Tests",phase,directory.toString());child.getInputStream().readAllBytes();require(child.waitFor()==75);require(Files.exists(file));
        try(var store=new LinkedStore(OWNER,directory.resolve("private"),VALIDATOR,CONSENT,List.of(directory.resolve("managed")),null)){String rootCap=grant(store,root);var operations=store.recover(OWNER);var operation=operations.stream().filter(r->r.record()!=null&&r.record().state().startsWith("ORIGINAL_")).findFirst().orElseThrow();require(Arrays.equals(operation.record().base(),LinkedStore.utf8("Original base\r\n")));require(operation.record().local().length==9000);var review=store.reviewRecovery(OWNER,operation.operation(),rootCap);require(store.repairRecovery(OWNER,review.ticket(),"base").state().equals("RECOVERY_REPAIRED_REOPEN_REQUIRED"));require(Files.readString(file).equals("Original base\r\n"));}
    }
}
